<style>.supplier-review-group{border:1px solid var(--line);border-radius:9px;margin-top:12px;overflow:hidden}.supplier-review-group summary{display:flex;justify-content:space-between;gap:12px;padding:13px 15px;background:var(--surface-2);cursor:pointer}.supplier-review-group summary span{color:var(--ink-dim)}.supplier-review-group .tablewrap{border:0;border-radius:0}.commercial-item{cursor:pointer;transition:background .14s,border-color .14s,box-shadow .14s}.commercial-item:hover{border-color:var(--primary);box-shadow:0 2px 10px rgba(36,144,239,.12)}.commercial-item.row-selected{background:var(--primary-soft);border-color:var(--primary)}.commercial-item.row-selected .field input,.commercial-item.row-selected .field select,.commercial-item.row-selected .field textarea{background:var(--surface)}</style>
<script>(function(){const cards=Array.from(document.querySelectorAll('.commercial-item'));function selected(card){const checked=!!card.querySelector('.group-select')?.checked;card.classList.toggle('row-selected',checked);card.setAttribute('aria-checked',String(checked));}function toggle(card){const checkbox=card.querySelector('.group-select');checkbox.checked=!checkbox.checked;selected(card);}function filter(card){const s=card.querySelector('.line-supplier'),m=card.querySelector('.line-method'),d=card.querySelector('.line-destination');if(!d)return;Array.from(d.options).forEach(o=>{if(!o.value)return;o.hidden=o.dataset.supplier!==s.value||(m.value&&o.dataset.method!==m.value);if(o.hidden&&o.selected)d.value='';});}function totals(){const groups={};let requestTotal=0;cards.forEach(c=>{const r=c.querySelector('.line-rate'),t=c.querySelector('.line-total'),s=c.querySelector('.line-supplier'),amount=(parseFloat(r.value)||0)*(parseFloat(r.dataset.quantity)||1);requestTotal+=amount;t.value=amount.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});const label=s.options[s.selectedIndex]?.text.split(' · ')[0]||'Unassigned';groups[label]=(groups[label]||0)+amount;});const money=n=>n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});const target=document.getElementById('supplierGroupTotals');if(target)target.innerHTML='<div class="tile"><div class="label">Complete Request Total</div><div class="value">TSh '+money(requestTotal)+'</div></div>'+Object.entries(groups).map(([n,t])=>'<div class="tile"><div class="label">'+n+'</div><div>TSh '+money(t)+'</div></div>').join('');}cards.forEach(c=>{c.addEventListener('click',event=>{if(event.target.closest('input,select,textarea,button,a,label'))return;toggle(c);});c.addEventListener('keydown',event=>{if(event.target!==c||!['Enter',' '].includes(event.key))return;event.preventDefault();toggle(c);});['.line-supplier','.line-method'].forEach(s=>c.querySelector(s)?.addEventListener('change',()=>{filter(c);totals();}));c.querySelector('.line-rate')?.addEventListener('input',totals);filter(c);selected(c);});document.getElementById('applySupplierGroup')?.addEventListener('click',()=>{const s=document.getElementById('bulk_supplier').value,m=document.getElementById('bulk_method').value;cards.filter(c=>c.querySelector('.group-select').checked).forEach(c=>{if(s)c.querySelector('.line-supplier').value=s;if(m)c.querySelector('.line-method').value=m;filter(c);});totals();});totals();})();</script>
